import sys


def main():
    input = sys.stdin.read
    data = input().split()
    if not data:
        return

    n = int(data[0])

    dario_wins = 0
    xerxes_wins = 0

    idx = 1
    for _ in range(n):
        d = int(data[idx])
        x = int(data[idx + 1])
        idx += 2

        # d ganha de (d + 1) % 5 e (d + 2) % 5
        if x == (d + 1) % 5 or x == (d + 2) % 5:
            dario_wins += 1
        else:
            xerxes_wins += 1

    if dario_wins > xerxes_wins:
        print("dario")
    else:
        print("xerxes")


if __name__ == "__main__":
    main()
